WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(134), (205655),(94782),(300439) ) AS x(dest_id) ), Txn_details AS ( SELECT DISTINCT rb_user_id, tin, DATE(date_of_issue) doi, DATE(date_of_journey) doj, source_location_id, destination_location_id, source_location, destination_location, ROW_NUMBER() OVER (PARTITION BY rb_user_id ORDER BY date_of_issue DESC) AS last_tin FROM "transaction"."bus_ticket_events" t INNER JOIN piligrim_dest_list p ON t.destination_location_id = p.dest_id WHERE date_of_issue >= TIMESTAMP '2025-02-28 18:30:00' AND date_of_issue < TIMESTAMP '2026-02-28 18:30:00' AND country_code = 'IND' AND business_unit = 'REDBUS_IN' AND event_class = 2 AND event_type = 101 AND source_location_id = 122 AND tin IS NOT NULL AND tin NOT IN ('', 'null') AND rb_user_id > 0 ), Base_users AS ( SELECT rb_user_id, COUNT(DISTINCT tin) txn_count FROM Txn_details GROUP BY 1 ) SELECT td.rb_user_id, ud.fullname, ud.hash_mobile, ud.hash_email, ud.gender, CAST(td.source_location_id AS VARCHAR) ||'-'|| CAST(td.destination_location_id AS VARCHAR) AS last_sd_id, (td.source_location ||'-'|| td.destination_location) AS last_route, td.doi AS last_doi, td.doj AS last_doj, bu.txn_count pilgrim_dest_txn_count FROM Txn_details td INNER JOIN Base_users bu ON bu.rb_user_id = td.rb_user_id AND txn_count BETWEEN 4 AND 10 LEFT JOIN "svoc"."svoc_booker" ud ON CAST(td.rb_user_id AS VARCHAR) = ud.rb_userid WHERE last_tin = 1 ORDER BY td.doi DESC LIMIT 10000
